53	    if (credits === undefined || typeof credits !== "number" || !isFinite(credits)) throw new Error("Missing or invalid credits");
54	    if (Math.abs(credits) > 100000) throw new Error("Credit adjustment exceeds maximum allowed (100,000)");
55	
56	    // Find user by email via auth admin
57	    const { data: authUsers } = await supabase.auth.admin.listUsers();
