59	    if (!targetUser) {
60	      return new Response(JSON.stringify({ error: "User not found" }), {
61	        status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
62	      });
63	    }
64	
65	    // Relative credit adjustment
66	    const { data: profile } = await supabase.from("profiles").select("credits").eq("user_id", targetUser.id).single();
67	    if (!profile) {
68	      return new Response(JSON.stringify({ error: "Profile not found" }), {
