75	    if (error) throw error;
76	
77	    // Audit trail for admin credit adjustments
78	    await supabase.from("admin_audit_logs").insert({
79	      admin_user_id: userId,
80	      action: "adjust_credits",
81	      entity_type: "user",
82	      entity_id: targetUser.id,
83	      details: {
84	        email,
85	        credits_delta: credits,
86	        old_credits: oldCredits,
87	        new_credits: newCredits,
88	      },
89	    });
90	
91	    return new Response(JSON.stringify({ success: true }), {
92	      headers: { ...corsHeaders, "Content-Type": "application/json" },
93	    });
