2	-- 1. Add inbound_email_domain to platform_config
3	ALTER TABLE public.platform_config
4	  ADD COLUMN IF NOT EXISTS inbound_email_domain text NOT NULL DEFAULT 'inbound.rankora.co';
5	
6	-- 2. Replace handle_new_user() with human-readable inbox email
7	CREATE OR REPLACE FUNCTION public.handle_new_user()
8	  RETURNS trigger
9	  LANGUAGE plpgsql
10	  SECURITY DEFINER
11	  SET search_path TO 'public'
12	AS $function$
13	DECLARE
14	  raw_email text;
15	  local_part text;
16	  domain text;
17	  base_inbox text;
18	  final_inbox text;
19	  suffix text;
20	  attempts int := 0;
21	BEGIN
22	  -- Get user email
23	  raw_email := lower(trim(NEW.raw_user_meta_data->>'email'));
24	  IF raw_email IS NULL OR raw_email = '' THEN
25	    raw_email := lower(trim(NEW.email));
26	  END IF;
27	
28	  -- Get inbound domain from config
29	  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
30	  IF domain IS NULL OR domain = '' THEN
31	    domain := 'inbound.rankora.co';
32	  END IF;
33	
34	  -- Extract and sanitize local part (before @)
35	  local_part := split_part(raw_email, '@', 1);
36	  -- Replace any char that isn't alphanumeric, dot, or hyphen
37	  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
38	  -- Collapse consecutive dots
39	  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
40	  -- Trim leading/trailing dots
41	  local_part := trim(both '.' from local_part);
42	
43	  IF local_part = '' THEN
44	    local_part := 'user';
45	  END IF;
46	
47	  base_inbox := local_part || '@' || domain;
48	  final_inbox := base_inbox;
49	
50	  -- Check for collisions
51	  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox) LOOP
52	    attempts := attempts + 1;
53	    suffix := substr(md5(random()::text), 1, 3);
54	    final_inbox := local_part || '.' || suffix || '@' || domain;
55	    IF attempts > 10 THEN
56	      -- Fallback to full random
57	      final_inbox := substr(md5(NEW.id::text || now()::text), 1, 12) || '@' || domain;
58	      EXIT;
59	    END IF;
60	  END LOOP;
61	
62	  INSERT INTO public.profiles (user_id, credits, inbox_email)
63	  VALUES (NEW.id, 5, final_inbox);
64	
65	  INSERT INTO public.user_roles (user_id, role)
66	  VALUES (NEW.id, 'user');
67	
68	  RETURN NEW;
69	END;
70	$function$;
71	
72	-- 3. Replace generate_job_inbox_email() with human-readable format
73	CREATE OR REPLACE FUNCTION public.generate_job_inbox_email()
74	  RETURNS trigger
75	  LANGUAGE plpgsql
76	  SECURITY DEFINER
77	  SET search_path TO 'public'
78	AS $function$
79	DECLARE
80	  user_inbox text;
81	  domain text;
82	  local_part text;
83	  short_id text;
84	BEGIN
85	  -- Get the job owner's inbox email
86	  SELECT inbox_email INTO user_inbox FROM public.profiles WHERE user_id = NEW.user_id;
87	
88	  -- Get inbound domain from config
89	  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
90	  IF domain IS NULL OR domain = '' THEN
91	    domain := 'inbound.rankora.co';
92	  END IF;
93	
94	  IF user_inbox IS NOT NULL AND user_inbox LIKE '%@%' THEN
95	    local_part := split_part(user_inbox, '@', 1);
96	  ELSE
97	    local_part := substr(md5(NEW.user_id::text), 1, 8);
98	  END IF;
99	
100	  -- Use first 8 chars of job ID as short identifier
101	  short_id := substr(NEW.id::text, 1, 8);
102	  NEW.inbox_email := local_part || '+j-' || short_id || '@' || domain;
103	
104	  RETURN NEW;
105	END;
106	$function$;
107	
108	-- 4. Create a reusable function for generating/regenerating user inbox
109	CREATE OR REPLACE FUNCTION public.generate_user_inbox_email(p_user_id uuid)
110	  RETURNS text
111	  LANGUAGE plpgsql
112	  SECURITY DEFINER
113	  SET search_path TO 'public'
114	AS $function$
115	DECLARE
116	  raw_email text;
117	  local_part text;
118	  domain text;
119	  base_inbox text;
120	  final_inbox text;
121	  suffix text;
122	  attempts int := 0;
123	BEGIN
124	  -- Get user email from auth.users
125	  SELECT lower(trim(email)) INTO raw_email FROM auth.users WHERE id = p_user_id;
126	  IF raw_email IS NULL OR raw_email = '' THEN
127	    raw_email := 'user' || substr(md5(p_user_id::text), 1, 6);
128	  END IF;
129	
130	  -- Get inbound domain
131	  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
132	  IF domain IS NULL OR domain = '' THEN
133	    domain := 'inbound.rankora.co';
134	  END IF;
135	
136	  -- Sanitize local part
137	  local_part := split_part(raw_email, '@', 1);
138	  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
139	  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
140	  local_part := trim(both '.' from local_part);
141	  IF local_part = '' THEN local_part := 'user'; END IF;
142	
143	  base_inbox := local_part || '@' || domain;
144	  final_inbox := base_inbox;
145	
146	  -- Collision check (exclude current user)
147	  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox AND user_id != p_user_id) LOOP
148	    attempts := attempts + 1;
149	    suffix := substr(md5(random()::text), 1, 3);
150	    final_inbox := local_part || '.' || suffix || '@' || domain;
151	    IF attempts > 10 THEN
152	      final_inbox := substr(md5(p_user_id::text || now()::text), 1, 12) || '@' || domain;
153	      EXIT;
154	    END IF;
155	  END LOOP;
156	
157	  -- Update profile
158	  UPDATE public.profiles SET inbox_email = final_inbox, updated_at = now() WHERE user_id = p_user_id;
159	
160	  RETURN final_inbox;
161	END;
162	$function$;
163	
164	-- 5. Re-attach trigger for jobs (ensure it exists)
165	DROP TRIGGER IF EXISTS trg_generate_job_inbox ON public.jobs;
166	CREATE TRIGGER trg_generate_job_inbox
167	  BEFORE INSERT ON public.jobs
168	  FOR EACH ROW
169	  WHEN (NEW.inbox_email IS NULL)
170	  EXECUTE FUNCTION public.generate_job_inbox_email();
