// ── Handler ───────────────────────────────────────────────────
serve(async (req) => {
  const headers = corsHeaders(req);
  if (req.method === "OPTIONS") return new Response(null, { headers });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const RESEND_API_KEY = Deno.env.get("RESEND_API_KEY") || "";
  const APP_URL = Deno.env.get("APP_URL") || "https://rankora.co";

  try {
    // ── Auth ──────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Authorization required" }), {
        status: 401,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const token = authHeader.replace("Bearer ", "");
    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
    if (claimsError || !claimsData?.claims) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }
    const callerId = claimsData.claims.sub as string;
    const callerEmail = claimsData.claims.email as string;

    // Service role client for DB operations
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // ── Parse & validate input ────────────────────────────────
    const body = (await req.json()) as InviteRequest;
    const { team_id, email, role } = body;

    if (!team_id || typeof team_id !== "string") {
      return new Response(JSON.stringify({ error: "Missing or invalid team_id" }), {
        status: 400,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    if (!email || typeof email !== "string") {
      return new Response(JSON.stringify({ error: "Missing or invalid email" }), {
        status: 400,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // Basic email format check
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email.trim())) {
      return new Response(JSON.stringify({ error: "Invalid email format" }), {
        status: 400,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    if (!role || !["admin", "member"].includes(role)) {
      return new Response(JSON.stringify({ error: "Role must be 'admin' or 'member'" }), {
        status: 400,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // Cannot invite yourself
    if (email.trim().toLowerCase() === callerEmail?.toLowerCase()) {
      return new Response(JSON.stringify({ error: "You cannot invite yourself" }), {
        status: 400,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // ── Verify caller is team admin/owner ─────────────────────
    const { data: membership } = await supabase
      .from("team_members")
      .select("role")
      .eq("team_id", team_id)
      .eq("user_id", callerId)
      .single();

    if (!membership || !["owner", "admin"].includes(membership.role)) {
      return new Response(JSON.stringify({ error: "Only team admins and owners can invite members" }), {
        status: 403,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // ── Fetch team details ────────────────────────────────────
    const { data: team, error: teamError } = await supabase
      .from("teams")
      .select("id, name")
      .eq("id", team_id)
      .single();

    if (teamError || !team) {
      return new Response(JSON.stringify({ error: "Team not found" }), {
        status: 404,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // ── Fetch caller's profile for display name ───────────────
    const { data: callerProfile } = await supabase
      .from("profiles")
      .select("id")
      .eq("user_id", callerId)
      .single();

    // Get display name from auth.users metadata
    const { data: callerAuthData } = await supabase.auth.admin.getUserById(callerId);
    const inviterName =
      callerAuthData?.user?.user_metadata?.full_name ||
      callerAuthData?.user?.user_metadata?.name ||
      callerEmail ||
      "A team member";

    // ── Upsert invitation (re-invite if previously declined/expired) ──
    const normalizedEmail = email.trim().toLowerCase();

    // Check if user is already a member
    const { data: existingMember } = await supabase
      .from("team_members")
      .select("id")
      .eq("team_id", team_id)
      .eq("user_id", (
        // Try to find existing user by email
        await supabase.auth.admin.listUsers().then(({ data }) =>
          data?.users?.find((u) => u.email?.toLowerCase() === normalizedEmail)?.id || ""
        )
      ))
      .maybeSingle();

    if (existingMember) {
      return new Response(JSON.stringify({ error: "User is already a team member" }), {
        status: 409,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // Upsert: if pending invitation exists, refresh token + expiry; otherwise insert
    const { data: existingInvite } = await supabase
      .from("team_invitations")
      .select("id, status")
      .eq("team_id", team_id)
      .eq("email", normalizedEmail)
      .maybeSingle();

    let invitation: Record<string, unknown>;

    if (existingInvite && existingInvite.status === "pending") {
      // Refresh the existing pending invite
      const { data: updated, error: updateError } = await supabase
        .from("team_invitations")
        .update({
          role,
          invited_by: callerId,
          token: crypto.randomUUID(),
          expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        })
        .eq("id", existingInvite.id)
        .select()
        .single();

      if (updateError) throw updateError;
      invitation = updated;
    } else if (existingInvite) {
      // Re-invite after declined/expired — update status back to pending
      const { data: updated, error: updateError } = await supabase
        .from("team_invitations")
        .update({
          role,
          invited_by: callerId,
          status: "pending",
          token: crypto.randomUUID(),
          created_at: new Date().toISOString(),
          expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        })
        .eq("id", existingInvite.id)
        .select()
        .single();

      if (updateError) throw updateError;
      invitation = updated;
    } else {
      // New invitation
      const { data: inserted, error: insertError } = await supabase
        .from("team_invitations")
        .insert({
          team_id,
          email: normalizedEmail,
          role,
          invited_by: callerId,
        })
        .select()
        .single();

      if (insertError) throw insertError;
      invitation = inserted;
    }

    // ── Send invite email ─────────────────────────────────────
    const inviteLink = `${APP_URL}/auth?invite=${invitation.token}`;
    const { subject, html } = buildInviteEmail({
      inviterName,
      teamName: team.name,
      role,
      inviteLink,
    });

    // Load email config from platform_config
    const { data: emailConfig } = await supabase
      .from("platform_config")
      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
      .limit(1)
      .single();

    const apiKey = emailConfig?.resend_api_key || RESEND_API_KEY;
    const fromEmail = emailConfig?.email_from_address || "noreply@rankora.co";
    const fromName = emailConfig?.email_from_name || "Rankora";

    if (apiKey && emailConfig?.outbound_email_enabled !== false) {
      const emailRes = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          from: `${fromName} <${fromEmail}>`,
          to: [normalizedEmail],
          subject,
          html,
        }),
      });

      if (!emailRes.ok) {
        const errBody = await emailRes.text();
        console.error("Resend error sending invite email:", emailRes.status, errBody);
        await logSystemError({
          function_name: "send-team-invite",
          error_type: "EMAIL_SEND_ERROR",
          severity: "warning",
          error_message: `Resend error: status=${emailRes.status} body=${errBody}`,
          user_id: callerId,
        });
        // Don't fail the whole request — invitation is created, email is best-effort
      }
    } else {
      console.warn("send-team-invite: email skipped (no API key or outbound disabled)");
    }

    return new Response(JSON.stringify({ invitation }), {
      status: 200,
      headers: { ...headers, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    console.error("send-team-invite error:", err);
    await logSystemError({
      function_name: "send-team-invite",
      error_type: "INVITE_ERROR",
      severity: "error",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...headers, "Content-Type": "application/json" } }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

// ── CORS ──────────────────────────────────────────────────────
const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

function corsHeaders(req: Request) {
  return {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  };
}

// ── Handler ───────────────────────────────────────────────────
serve(async (req) => {
  const headers = corsHeaders(req);
  if (req.method === "OPTIONS") return new Response(null, { headers });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  try {
    // ── Parse input ───────────────────────────────────────────
    const body = await req.json() as { token?: string };
    const { token } = body;

    if (!token || typeof token !== "string" || token.trim() === "") {
      return new Response(JSON.stringify({ error: "Missing or invalid invitation token" }), {
        status: 400,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // Service role client — needed to bypass RLS for reading/updating invitations
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // ── Validate token ────────────────────────────────────────
    const { data: invitation, error: inviteError } = await supabase
      .from("team_invitations")
      .select("id, team_id, email, role, status, expires_at")
      .eq("token", token.trim())
      .maybeSingle();

    if (inviteError) throw inviteError;

    if (!invitation) {
      return new Response(JSON.stringify({ error: "Invitation not found or already used" }), {
        status: 404,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    if (invitation.status !== "pending") {
      const statusMessages: Record<string, string> = {
        accepted: "This invitation has already been accepted",
        declined: "This invitation was declined",
        expired: "This invitation has expired",
      };
      return new Response(
        JSON.stringify({ error: statusMessages[invitation.status] || "Invitation is no longer valid" }),
        { status: 410, headers: { ...headers, "Content-Type": "application/json" } }
      );
    }

    if (new Date(invitation.expires_at) < new Date()) {
      // Mark as expired
      await supabase
        .from("team_invitations")
        .update({ status: "expired" })
        .eq("id", invitation.id);

      return new Response(JSON.stringify({ error: "This invitation has expired. Please ask a team admin to send a new one." }), {
        status: 410,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // ── Determine authenticated user ──────────────────────────
    const authHeader = req.headers.get("Authorization");
    let userId: string | null = null;
    let userEmail: string | null = null;

    if (authHeader) {
      const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
      const supabaseUser = createClient(SUPABASE_URL, anonKey, {
        global: { headers: { Authorization: authHeader } },
      });
      const tokenStr = authHeader.replace("Bearer ", "");
      const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(tokenStr);

      if (!claimsError && claimsData?.claims) {
        userId = claimsData.claims.sub as string;
        userEmail = claimsData.claims.email as string;
      }
    }

    // Must be signed in to accept
    if (!userId) {
      return new Response(
        JSON.stringify({
          error: "You must be signed in to accept this invitation",
          requires_auth: true,
          // Pass back safe metadata so the frontend can pre-fill email
          invite_email: invitation.email,
          team_id: invitation.team_id,
        }),
        { status: 401, headers: { ...headers, "Content-Type": "application/json" } }
      );
    }

    // Email validation: the signed-in user's email must match the invitation
    if (
      userEmail &&
      invitation.email &&
      userEmail.toLowerCase() !== invitation.email.toLowerCase()
    ) {
      return new Response(
        JSON.stringify({
          error: `This invitation was sent to ${invitation.email}. Please sign in with that account to accept it.`,
          email_mismatch: true,
          invite_email: invitation.email,
        }),
        { status: 403, headers: { ...headers, "Content-Type": "application/json" } }
      );
    }

    // ── Check not already a member ────────────────────────────
    const { data: existingMember } = await supabase
      .from("team_members")
      .select("id, role")
      .eq("team_id", invitation.team_id)
      .eq("user_id", userId)
      .maybeSingle();

    if (existingMember) {
      // Already a member — mark invitation accepted and return success
      await supabase
        .from("team_invitations")
        .update({ status: "accepted" })
        .eq("id", invitation.id);

      return new Response(
        JSON.stringify({
          success: true,
          already_member: true,
          team_id: invitation.team_id,
          role: existingMember.role,
        }),
        { status: 200, headers: { ...headers, "Content-Type": "application/json" } }
      );
    }

    // ── Insert team member ────────────────────────────────────
    const { error: memberError } = await supabase
      .from("team_members")
      .insert({
        team_id: invitation.team_id,
        user_id: userId,
        role: invitation.role,
      });

    if (memberError) {
      // Handle unique constraint violation gracefully
      if (memberError.code === "23505") {
        // Already inserted (race condition) — just mark accepted
      } else {
        throw memberError;
      }
    }

    // ── Mark invitation accepted ──────────────────────────────
    const { error: updateError } = await supabase
      .from("team_invitations")
      .update({ status: "accepted" })
      .eq("id", invitation.id);

    if (updateError) throw updateError;

    // ── Fetch team name for the response ──────────────────────
    const { data: team } = await supabase
      .from("teams")
      .select("id, name")
      .eq("id", invitation.team_id)
      .single();

    return new Response(
      JSON.stringify({
        success: true,
        team_id: invitation.team_id,
        team_name: team?.name ?? null,
        role: invitation.role,
      }),
      { status: 200, headers: { ...headers, "Content-Type": "application/json" } }
    );
  } catch (err: unknown) {
    console.error("accept-team-invite error:", err);
    await logSystemError({
      function_name: "accept-team-invite",
      error_type: "ACCEPT_INVITE_ERROR",
      severity: "error",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...headers, "Content-Type": "application/json" } }
    );
  }
});

